TASK: Fix a bug in /gin/response_writer.go and verify it.

Context: `responseWriter.WriteHeader(code int)` currently is:

    func (w *responseWriter) WriteHeader(code int) {
        if code > 0 && w.status != code {
            if w.Written() {
                debugPrint("[WARNING] Headers were already written. Wanted to override status code %d with %d", w.status, code)
            }
            w.status = code
        }
    }

The bug: when the response has already been written (`w.Written()` is true, i.e. the status line was already sent to the client), the method still overwrites `w.status` with the new code. That makes `w.Status()` report a status code that was never actually sent to the client (the underlying http.ResponseWriter already got the old code), and it also means a later `WriteHeaderNow()`/`Write` can no longer send the right code. The expected behaviour is that once headers have been written, the status code is immutable: only the warning is printed and the method returns without changing `w.status`.

FIX: add a `return` inside the `if w.Written() { ... }` block, so the method becomes:

    func (w *responseWriter) WriteHeader(code int) {
        if code > 0 && w.status != code {
            if w.Written() {
                debugPrint("[WARNING] Headers were already written. Wanted to override status code %d with %d", w.status, code)
                return
            }
            w.status = code
        }
    }

Change nothing else in the file and touch no other file.

VERIFICATION (all must be run and reported verbatim):
1. cd /gin && gofmt -l response_writer.go   (must print nothing)
2. cd /gin && go build ./... && go vet ./... 2>&1 | tail -20
3. cd /gin && go test -run 'TestResponseWriter' -v . 2>&1 | tail -40  (all must PASS)
4. Create a TEMPORARY test file /gin/zz_tmp_status_test.go in package gin with exactly this content:

package gin

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestTmpResponseWriterStatusCode(t *testing.T) {
	testWriter := httptest.NewRecorder()
	writer := &responseWriter{}
	writer.reset(testWriter)
	w := ResponseWriter(writer)

	w.WriteHeader(http.StatusOK)
	w.WriteHeaderNow()

	assert.Equal(t, http.StatusOK, testWriter.Code)

	w.WriteHeader(http.StatusNotFound)
	assert.Equal(t, http.StatusOK, testWriter.Code)
	assert.Equal(t, http.StatusOK, w.Status())
}

func TestTmpResponseWriterStatusCodeBeforeWrite(t *testing.T) {
	testWriter := httptest.NewRecorder()
	writer := &responseWriter{}
	writer.reset(testWriter)
	w := ResponseWriter(writer)

	// before anything is written, the last WriteHeader wins
	w.WriteHeader(http.StatusOK)
	w.WriteHeader(http.StatusNotFound)
	assert.Equal(t, http.StatusNotFound, w.Status())
	w.WriteHeaderNow()
	assert.Equal(t, http.StatusNotFound, testWriter.Code)
}

Run: cd /gin && go test -run 'TestTmpResponseWriter' -v . 2>&1 | tail -30  (must PASS)
5. DELETE /gin/zz_tmp_status_test.go (rm -f) and confirm it is gone with `ls /gin/zz_tmp_status_test.go`.
6. Run the FULL suite: cd /gin && go test ./... 2>&1 | tail -30 and report whether anything fails. If any pre-existing test fails, report the exact failing test name and output, and say whether it is caused by this change (you can check by temporarily reverting the change with `git stash`/`git checkout -- response_writer.go`... do NOT do that: instead just report the failure output and reason about it).

